970	// ════════════════════════════════════════════════════════════════════════
971	//  P2 — OUTPUT-STATIONARY dW (the Q2 deliverable). Each of the 9 weight
972	//  matrices dW = dYᵀ @ X (K=T) is split into 64×N output tiles; tile_id %
973	//  nCTA owns each (fixed every step → determinism + L2 warmth). The owner CTA
974	//  contracts the FULL token dimension itself (ascending-t, no float atomics, no
975	//  partials) via the validated dW orientation (tc_gemm_block_unpipelined with
976	//  BOTH operands transposed-staged, MaxAtomsM=1 → one 64×N tile, 64 acc regs/
977	//  thread, no spill). Writes the tile into `grad` (the reduced-grad output).
978	//
979	//  The 9 weights, in dec_layout tensor-index order, with their (dY,X) acts and
980	//  the contraction length K (T for per-position weights, B for the head).
981	// ════════════════════════════════════════════════════════════════════════
982	struct DecDwSpec {
983	    const __nv_bfloat16* dY;   // [K, Nout]
984	    const __nv_bfloat16* X;    // [K, Kin]
985	    int Nout; int Kin; int K;
986	    int grad_off;              // element offset of this weight in `grad`
987	    const __nv_bfloat16* dY_bias;  // same as dY (bias db = Σ_K dY)
988	    int bias_off;              // element offset of the bias in `grad`
989	};
990	
991	// Build the 9 specs (called by all CTAs; cheap). T = B*kSeq.
992	__device__ __forceinline__ void dectc_build_dw_specs(
993	        const DecActs& acts, int B, int T, DecDwSpec spec[9]) {
994	    // dec_layout offsets: see kDecOffsets. Weight tensor indices (and bias idx):
995	    //   L0: in_w=2 (in_b=3), out_w=4 (out_b=5), ff0_w=10 (ff0_b=11), ff2_w=12 (ff2_b=13)
996	    //   L1: in_w=14(15), out_w=16(17), ff0_w=22(23), ff2_w=24(25)
997	    //   head: out_w=28 (out_b=29)
998	    const int wi[9]  = {2,4,10,12, 14,16,22,24, 28};
999	    const int bi[9]  = {3,5,11,13, 15,17,23,25, 29};
1000	    for (int s = 0; s < 8; ++s) {
1001	        const int li = s / 4, kind = s % 4;
1002	        DecDwSpec& sp = spec[s];
1003	        sp.K = T; sp.grad_off = kDecOffsets[wi[s]]; sp.bias_off = kDecOffsets[bi[s]];
1004	        if (kind == 0)      { sp.dY = acts.dY_qkv[li]; sp.X = acts.X_in[li];  sp.Nout = 3 * dec::kD; sp.Kin = dec::kD;   }
1005	        else if (kind == 1) { sp.dY = acts.dY_a[li];   sp.X = acts.X_ctx[li]; sp.Nout = dec::kD;     sp.Kin = dec::kD;   }
1006	        else if (kind == 2) { sp.dY = acts.dY_ff0[li]; sp.X = acts.X_x1[li];  sp.Nout = dec::kDff;   sp.Kin = dec::kD;   }
1007	        else                { sp.dY = acts.dY_ff2[li]; sp.X = acts.X_gact[li];sp.Nout = dec::kD;     sp.Kin = dec::kDff; }
1008	        sp.dY_bias = sp.dY;
1009	    }
1010	    DecDwSpec& hd = spec[8];
1011	    hd.dY = acts.dY_logits; hd.X = acts.X_hn; hd.Nout = dec::kVocab; hd.Kin = dec::kD; hd.K = B;
1012	    hd.grad_off = kDecOffsets[28]; hd.bias_off = kDecOffsets[29]; hd.dY_bias = hd.dY;
1013	}
1014	
1015	// Total number of 64×N dW output tiles across the 9 weights (for the tile loop).
1016	template <int N>
1017	__device__ __forceinline__ int dectc_dw_total_tiles(const DecDwSpec spec[9]) {
1018	    int n = 0;
1019	    for (int s = 0; s < 9; ++s)
1020	        n += ((spec[s].Nout + 63) / 64) * ((spec[s].Kin + N - 1) / N);
1021	    return n;
1022	}
1023	
1024	// Run ONE global dW tile `gt` (if it belongs to this CTA): decode (weight, M-atom,
1025	// N-tile), then contract K via the dW GEMM into grad[grad_off]. MaxAtomsM=1.
1026	template <int N>
1027	__device__ __forceinline__ void dectc_dw_run_tile(
1028	        const DecDwSpec spec[9], int gt, float* __restrict__ grad,
1029	        __nv_bfloat16* sA, __nv_bfloat16* sB) {
1030	    // Decode gt → (s, m_atom, n_tile).
1031	    int acc = 0, s = 0, m_atom = 0, n_tile = 0;
1032	    for (s = 0; s < 9; ++s) {
1033	        const int ma = (spec[s].Nout + 63) / 64;
1034	        const int nt = (spec[s].Kin + N - 1) / N;
1035	        if (gt < acc + ma * nt) { int loc = gt - acc; m_atom = loc / nt; n_tile = loc % nt; break; }
1036	        acc += ma * nt;
1037	    }
1038	    const DecDwSpec& sp = spec[s];
1039	    const int mbase = m_atom * 64;
1040	    const int n0 = n_tile * N;
1041	    const int n_real = (sp.Kin - n0) < N ? (sp.Kin - n0) : N;
1042	    const int k_steps = sp.K / wgs::kWgmmaAtomK;     // K = T or B (must be /16; padded by caller)
1043	    const int Nout = sp.Nout, Kin = sp.Kin;
1044	    const __nv_bfloat16* dY = sp.dY; const __nv_bfloat16* X = sp.X;
1045	    // The engine (tc_gemm_block_unpipelined, mbase0=mbase, m_atoms=1) passes the
1046	    // GLOBAL row m = mbase + mn to srcA/out (it adds mbase0 itself), so the
1047	    // accessors use `m` RAW — adding mbase again would double-count (the selftest
1048	    // passes mbase0=0 and uses m raw; we pass mbase0=mbase and likewise use m raw).
1049	    // A[m=out, k=t] = dY[t,out]  (transposed read); B[n=in, k=t] = X[t,in] (transposed).
1050	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
1051	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
1052	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
1053	        int nn = n0 + n; return nn < Kin ? X[(int64_t)k * Kin + nn] : __float2bfloat16(0.f); };
1054	    auto out  = [&] (int m, int n, float v) {
1055	        if (m < Nout) grad[sp.grad_off + (int64_t)m * Kin + n0 + n] = v; };
1056	    tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/1>(
1057	        mbase, /*m_atoms=*/1, n_real, k_steps, srcA, srcB, out, sA, sB);
1058	}
1059	
1060	// Biases db = Σ_K dY  (per output row). Work-stealing over the 9 weights' rows is
1061	// overkill; instead each CTA strides ALL bias outputs (cheap: ≤ 3d=384 rows × 9).
1062	// Single owner per output element (thread strides global bias-row index) → no atomics.
1063	__device__ __forceinline__ void dectc_dw_biases(
1064	        const DecDwSpec spec[9], float* __restrict__ grad) {
1065	    for (int s = 0; s < 9; ++s) {
1066	        const DecDwSpec& sp = spec[s];
1067	        for (int o = threadIdx.x; o < sp.Nout; o += blockDim.x) {
1068	            float accv = 0.0f;
1069	            for (int k = 0; k < sp.K; ++k) accv += __bfloat162float(sp.dY_bias[(int64_t)k * sp.Nout + o]);
1070	            grad[sp.bias_off + o] = accv;
1071	        }
1072	    }
1073	}
1074	
1075	// ════════════════════════════════════════════════════════════════════════
1076	//  P2 — EMBEDDING owner-scan (tok/pos). dh0 [T,d] (bf16) holds grad wrt h0.
1077	//    tok grad: row r (token id) of tok.weight → owner CTA (r % nCTA); the owner
1078	//    scans ALL T tokens in ascending t, accumulating dh0[t,:] for tokens whose
1079	//    id == r. pos grad: row p → owner; sums dh0[t,:] over t with (t%S)==p.
1080	//    Fixed t-order + single owner per row → deterministic, atomic-free.
1081	//    `tok_ids` is HBM int32 [T]. Writes grad[tok_off..], grad[pos_off..].
1082	// ════════════════════════════════════════════════════════════════════════
1083	__device__ __forceinline__ void dectc_embed_owner_scan(
1084	        const DecActs& acts, const int* __restrict__ tok_ids, int T,
1085	        float* __restrict__ grad, int cta, int nCTA) {
1086	    const int tok_off = kDecOffsets[0];   // tok.weight [V,d]
1087	    const int pos_off = kDecOffsets[1];   // pos.weight [S,d]
1088	    // tok rows owned by this CTA: r in [0,V) with r % nCTA == cta.
1089	    for (int r = cta; r < dec::kVocab; r += nCTA) {
1090	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1091	            float accv = 0.0f;
1092	            for (int t = 0; t < T; ++t)
1093	                if (tok_ids[t] == r) accv += __bfloat162float(acts.dh0[(int64_t)t * dec::kD + j]);
1094	            grad[tok_off + (int64_t)r * dec::kD + j] = accv;
1095	        }
1096	    }
1097	    // pos rows owned by this CTA: p in [0,S) with p % nCTA == cta.
1098	    for (int p = cta; p < dec::kSeq; p += nCTA) {
1099	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1100	            float accv = 0.0f;
1101	            for (int t = 0; t < T; ++t)
1102	                if ((t % dec::kSeq) == p) accv += __bfloat162float(acts.dh0[(int64_t)t * dec::kD + j]);
1103	            grad[pos_off + (int64_t)p * dec::kD + j] = accv;
1104	        }
1105	    }
1106	}
1107	
1108	// ════════════════════════════════════════════════════════════════════════
1109	//  P2 — LN-vector grad reduce. The 10 γ/β grads were accumulated tile-locally
1110	//    into each CTA's lnvec partials [kNumLnVec × d]; sum across CTAs in
1111	//    ASCENDING CTA index (deterministic) into the 10 dec_layout slots of grad.
1112	//    `lnvec_base` is the start of the [nCTA × kLnVecElems] partial region.
1113	// ════════════════════════════════════════════════════════════════════════
1114	__device__ __forceinline__ void dectc_lnvec_reduce(
1115	        const float* __restrict__ lnvec_base, float* __restrict__ grad,
1116	        int nCTA, int cta) {
1117	    // Each CTA reduces a subset of the 10 LN tensors (round-robin by tensor).
1118	    for (int v = cta; v < kNumLnVec; v += nCTA) {
1119	        const int goff = kLnVecTensorIdx[v];
1120	        const int64_t gbase = kDecOffsets[goff];
1121	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1122	            float accv = 0.0f;
1123	            for (int c = 0; c < nCTA; ++c)
1124	                accv += lnvec_base[(int64_t)c * kLnVecElems + (int64_t)v * dec::kD + j];
1125	            grad[gbase + j] = accv;
1126	        }
1127	    }
1128	}
