291	//  WGMMA CELL DRIVER (DESIGN-TC-PIPELINE.md Fork B, R2.3). Compiled only under
292	//  the wgmma token; the scalar path above is untouched.
293	// ════════════════════════════════════════════════════════════════════════════
294	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
295	
296	// TC megakernel threads: 256 (the engine's producer+consumer warpgroup layout;
297	// wgmma is warpgroup-scoped on threads 0..127). We do NOT apply the scalar
298	// path's asymmetric setmaxnreg (dealloc<32> on WG0) — that would STARVE the MMA
299	// warpgroup (WG0 issues the wgmma; a 128-wide accumulator needs 64 fp32 regs/
300	// thread). The validated selftest ran no split; we match it.
301	#define SG_TC_MEGA_BLOCK 256
302	
303	// ── smem arena for the unpipelined engine: one A(64×16) + one B(N×16) bf16 tile
304	//    + the 256-float reduction slot. 16B-aligned. N = SG_TUNED_TILE_N. The 9 dW
305	//    specs live here too (identical for all threads → shared, not per-thread
306	//    stack: keeps the launch's local-memory reservation small so the persistent
307	//    kernel places on a memory-tight GPU). ──
308	struct DecTcSmem {
309	    __nv_bfloat16 sA[64 * 16];
310	    __nv_bfloat16 sB[SG_TUNED_TILE_N * 16];
311	    float red[256];
312	    dectc::DecDwSpec spec[9];
313	};
314	
315	// ── TC workspace layout (carved from tok.workspace; the host sizes it for the
316	//    TC path — see dec_tc_workspace_floats). Regions (float units):
317	//      [0 .. acts_f)                      : DecActs bf16 region (reinterpreted)
318	//      [acts_f .. acts_f + nCTA*scratch)  : per-CTA tile scratch (f32)
319	//      [.. + nCTA*kLnVecElems)            : per-CTA LN-vec partials (f32)
320	//      [.. + nCTA)                        : per-CTA loss slots (f32)
321	//      [.. + 1)                           : reduced scalar loss (host reads it)
322	//    acts_f = ceil(acts_bf16 / 2). ──
323	__host__ __device__ __forceinline__ int64_t dec_tc_acts_floats(int T, int B) {
324	    // mirror dectc::dec_acts_bind's running offset (bf16 elems) → floats.
325	    const int64_t d = dec::kD, dff = dec::kDff, V = dec::kVocab, L = dec::kLayers;
326	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
327	    int64_t bf = 0;
328	    for (int li = 0; li < L; ++li) bf += Td + Td + Td + Tff + T3d + Td + Tff + Td;
329	    bf += (int64_t)B * d + (int64_t)B * V + Td;     // X_hn + dY_logits + dh0
330	    return (bf + 1) / 2;
331	}
332	__host__ __device__ __forceinline__ int64_t dec_tc_workspace_floats(int T, int B, int nCTA) {
333	    return dec_tc_acts_floats(T, B)
334	         + (int64_t)nCTA * dectc::dec_tile_scratch_total_f32()
335	         + (int64_t)nCTA * dectc::kLnVecElems
336	         + nCTA + 1;
337	}
338	
339	template <OptId Opt>
340	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
341	fused_decoder_megakernel_tc(PersistentContext ctx,
342	                            float* __restrict__ params,
343	                            DecoderTokenCtx tok,
344	                            float* __restrict__ grad,
345	                            float lr, int step, FusedOptState st) {
346	    __shared__ DecTcSmem sm;
347	    GridBarrier bar = ctx.barrier();
348	    const int cta = blockIdx.x;
349	    const int nCTA = (int)ctx.n_ctas;
350	    const int B = tok.B;
351	    const int T = B * dec::kSeq;
352	
353	    // Workspace partition.
354	    float* ws = tok.workspace;
355	    const int64_t acts_f = dec_tc_acts_floats(T, B);
356	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
357	    float* scratch_base = ws + acts_f;
358	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
359	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
360	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
361	    float* loss_out   = loss_part + nCTA;
362	
363	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
364	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
365	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
366	
367	    DecWeights w = dec_bind(params);
368	
369	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
370	    //    written-once → no pre-zero). ──
371	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
372	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
373	    bar.sync();   // B0
374	
375	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
376	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
377	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
378	    const int nrows_tile = dectc::kTileM;
379	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
380	    float nll_acc = 0.0f;
381	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
382	        const int g0 = ti * nrows_tile;
383	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
384	        float nll = dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
385	                                              sm.sA, sm.sB, sm.red);
386	        dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
387	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
388	        if (threadIdx.x == 0) nll_acc += nll;
389	        __syncthreads();
390	    }
391	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
392	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
393	
394	    // ── P2: assemble all 30 grads into `grad`. dW output-stationary (gt %
395	    //    nCTA), biases, embedding owner-scan, LN-vec reduce. No partials. The 9
396	    //    dW specs are built into SHARED smem (thread 0; identical for all) so the
397	    //    9-spec array is NOT on every thread's stack (shrinks the launch's local
398	    //    reservation — the persistent kernel must place on a memory-tight GPU). ──
399	    if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
400	    __syncthreads();
401	    dectc::DecDwSpec* spec = sm.spec;
402	    const int n_dw = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
403	    for (int gt = cta; gt < n_dw; gt += nCTA)
404	        dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
405	    dectc::dectc_dw_biases(spec, grad);
406	    dectc::dectc_embed_owner_scan(acts, tok.tokens, T, grad, cta, nCTA);
407	    dectc::dectc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
408	    // Loss reduce (fp64) by CTA 0.
409	    if (cta == 0 && threadIdx.x == 0) {
410	        double s = 0.0;
411	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
412	        *tok.loss_out = (float)(s / (double)B);
413	    }
414	    (void)loss_out;
415	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
416	
417	    // ── P3: scalar optimizer tail over the reduced grad (REUSED verbatim). ──
418	    st.lr = lr;
419	    {
420	        __shared__ int task_slot;
421	        TaskQueue q = ctx.queue();
422	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
423	             t = q.next_block(&task_slot)) {
424	            const int n = kDecSizes[t];
425	            const int64_t off = (int64_t)kDecOffsets[t];
426	            const FusedOptState ts = rebase_state<Opt>(st, off);
427	            float* __restrict__ p = params + off;
428	            const float* __restrict__ gg = grad + off;
429	            for (int i = threadIdx.x; i < n; i += blockDim.x)
430	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
431	        }
432	    }
433	}
434	
435	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
436	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas),
437	// so any cap is hang-safe as long as the workspace + dW-tile/embedding ownership
438	// use the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
439	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
440	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
441	// nCTA (the dW/embedding owner maps are functions of nCTA).
442	template <OptId Opt>
443	cudaError_t launch_fused_decoder_megakernel_tc(
444	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
445	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
446	        int ncta_cap = 0) {
447	    int dev = 0;
448	    cudaError_t err = cudaGetDevice(&dev);
449	    if (err != cudaSuccess) return err;
450	    int n_sms = 0;
451	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
452	    if (err != cudaSuccess) return err;
453	
454	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
455	    // (0 here — DecTcSmem is static). If the static smem + 200-reg consumer
456	    // can't place one block/SM, REFUSE (the grid barrier would hang).
457	    int occ = 0;
458	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
459	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
460	        /*dynamicSMemBytes=*/0);
461	    if (err != cudaSuccess) return err;
462	    if (occ < 1) return cudaErrorLaunchOutOfResources;
463	
464	    unsigned launch_ctas = (unsigned)n_sms;
465	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
466	    ctx.n_ctas = launch_ctas;
467	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms).
468	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
469	
470	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
471	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
472	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
473	
474	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
475	    fused_decoder_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
476	        ctx, params, tok, grad, lr, step, st);
477	    return cudaGetLastError();
478	}
