113	// ── Per-CTA scratch for one sample. POD placed in DYNAMIC smem (one instance per
114	//    CTA; sizeof is static_asserted in vit_layout.cuh). The arrays that must
115	//    survive fwd→bwd within a layer are kept; the rest are recomputed. All
116	//    [kSeq × width] row-major (row = position). ────────────────────────────────
117	struct VitSampleSmem {
118	    // This sample's image patches (FLOAT) — kept live so the embedding backward
119	    // can form patch_proj's weight/bias grad. [kNPatch × kPatch] = 16*49.
120	    float patch[vit::kNPatch][vit::kPatch];             // 16*49 = 784 f
121	    // Per-layer cached INPUT to each layer (h before the layer) — the only
122	    // cross-layer state kept, so the backward can recompute each layer's fwd.
123	    float layer_in[vit::kLayers][vit::kSeq][vit::kD];   // 2*17*128 = 4352 f
124	    // The final-norm input (last layer output, all positions) for bwd.
125	    float final_in[vit::kSeq][vit::kD];                 // 17*128 = 2176 f
126	    // Scratch reused within a single layer's fwd or bwd (one layer live):
127	    float qkv[vit::kSeq][3 * vit::kD];                  // 17*384 = 6528 f
128	    float ctx[vit::kSeq][vit::kD];                      // 17*128 = 2176 f
129	    float x1[vit::kSeq][vit::kD];                       // 17*128 = 2176 f (post n1)
130	    float ff0[vit::kSeq][vit::kDff];                    // 17*512 = 8704 f (pre-gelu)
131	    float gact[vit::kSeq][vit::kDff];                   // 17*512 = 8704 f (post-gelu)
132	    float attn[vit::kHeads][vit::kSeq][vit::kSeq];      // 4*17*17 = 1156 f
133	    // LayerNorm caches (xhat + inv_std) for n1, n2, final — per position.
134	    float n1_xhat[vit::kSeq][vit::kD];
135	    float n1_inv[vit::kSeq];
136	    float n2_xhat[vit::kSeq][vit::kD];
137	    float n2_inv[vit::kSeq];
138	    float fn_xhat[vit::kSeq][vit::kD];
139	    float fn_inv[vit::kSeq];
140	    // Backward adjoints carried across sub-steps (one layer live), per position.
141	    float dh[vit::kSeq][vit::kD];                       // running grad wrt block out
142	    float logits[vit::kVocab];                          // CLS-pos logits (bwd)
143	    // Dedicated attention-backward dscores buffer (NOT aliased over `attn`, so the
144	    // forward softmax weights stay live while dv/dq/dk read them).
145	    float dsc[vit::kHeads][vit::kSeq][vit::kSeq];
146	    // Reductions across threads for row stats (mean / max / dot). 256 threads.
