243	// ── Block-wide reductions (256 threads) over a value `v`. The smem `red` slot is
244	//    the VitSampleSmem::red array. All threads must call. ──────────────────────
245	__device__ __forceinline__ float vit_block_sum(float v, float* red) {
246	    const unsigned full = 0xffffffffu;
247	    #pragma unroll
248	    for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(full, v, o);
249	    const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
250	    if (lane == 0) red[warp] = v;
251	    __syncthreads();
252	    const int nwarp = (blockDim.x + 31) >> 5;
253	    float r = 0.0f;
254	    if (warp == 0) {
255	        float p = (lane < nwarp) ? red[lane] : 0.0f;
256	        #pragma unroll
257	        for (int o = 16; o > 0; o >>= 1) p += __shfl_down_sync(full, p, o);
258	        if (lane == 0) red[0] = p;
259	    }
260	    __syncthreads();
261	    r = red[0];
262	    __syncthreads();
263	    return r;
264	}
265	__device__ __forceinline__ float vit_block_max(float v, float* red) {
266	    const unsigned full = 0xffffffffu;
267	    #pragma unroll
268	    for (int o = 16; o > 0; o >>= 1) {
269	        float other = __shfl_down_sync(full, v, o);
270	        v = fmaxf(v, other);
271	    }
272	    const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
273	    if (lane == 0) red[warp] = v;
274	    __syncthreads();
275	    const int nwarp = (blockDim.x + 31) >> 5;
276	    float r;
277	    if (warp == 0) {
278	        float p = (lane < nwarp) ? red[lane] : -CUDART_INF_F;
279	        #pragma unroll
280	        for (int o = 16; o > 0; o >>= 1) {
281	            float other = __shfl_down_sync(full, p, o);
282	            p = fmaxf(p, other);
283	        }
284	        if (lane == 0) red[0] = p;
285	    }
286	    __syncthreads();
287	    r = red[0];
288	    __syncthreads();
289	    return r;
290	}
