343	// Self-attention (FULL — no causal mask) for one layer, CTA-cooperative. Reads
344	// q,k,v from sm->qkv columns [0,d),[d,2d),[2d,3d); writes softmax weights into
345	// sm->attn and the merged context into sm->ctx. Mirrors the oracle's attention.
346	__device__ __forceinline__ void vit_attention(VitSampleSmem* sm) {
347	    const float scale = vit::attn_scale();
348	    // One thread per (head, qpos) computes that row's softmax + ctx slice.
349	    // kSeq*kHeads = 68 rows; threads stride. Each thread loops d_head.
350	    for (int r = threadIdx.x; r < vit::kHeads * vit::kSeq; r += blockDim.x) {
351	        const int hh = r / vit::kSeq;     // head
352	        const int qi = r % vit::kSeq;     // query position
353	        const int qoff = hh * vit::kDhead;
354	        const float* qrow = &sm->qkv[qi][qoff];   // [dhead]
355	        float maxs = -CUDART_INF_F;
356	        float sc[vit::kSeq];
357	        #pragma unroll
358	        for (int kj = 0; kj < vit::kSeq; ++kj) {   // FULL: every key position
359	            const float* krow = &sm->qkv[kj][vit::kD + qoff];  // k block
360	            float dot = 0.0f;
361	            #pragma unroll
362	            for (int t = 0; t < vit::kDhead; ++t) dot += qrow[t] * krow[t];
363	            sc[kj] = dot * scale;
364	            maxs = fmaxf(maxs, sc[kj]);
365	        }
366	        float denom = 0.0f;
367	        #pragma unroll
368	        for (int kj = 0; kj < vit::kSeq; ++kj) {
369	            float e = __expf(sc[kj] - maxs);
370	            sc[kj] = e; denom += e;
371	        }
372	        float invd = 1.0f / denom;
373	        #pragma unroll
374	        for (int kj = 0; kj < vit::kSeq; ++kj)
375	            sm->attn[hh][qi][kj] = sc[kj] * invd;
376	        // ctx[qi, qoff+t] = sum_kj attn * v[kj, qoff+t]  (FULL: all kj)
377	        #pragma unroll
378	        for (int t = 0; t < vit::kDhead; ++t) {
379	            float acc = 0.0f;
380	            #pragma unroll
381	            for (int kj = 0; kj < vit::kSeq; ++kj)
382	                acc += sm->attn[hh][qi][kj] * sm->qkv[kj][2 * vit::kD + qoff + t];
383	            sm->ctx[qi][qoff + t] = acc;
384	        }
385	    }
386	    __syncthreads();
387	}
388	
389	// ────────────────────────────────────────────────────────────────────────────
390	//  FORWARD for one sample (CTA-cooperative). The sample's patches must already
391	//  be loaded into sm->patch. Writes the per-layer input cache + final-norm input
392	//  + CLS-position logits into `sm`, and returns the sample NLL (all threads see
393	//  the same value). Recompute-friendly: the layer-local scratch reflects the LAST
394	//  layer processed; backward recomputes per layer from layer_in.
395	// ────────────────────────────────────────────────────────────────────────────
396	__device__ float vit_forward_sample(const VitWeights& w, int target,
397	                                     VitSampleSmem* sm) {
398	    // Embedding: position 0 = cls + pos[0]; positions 1..16 = patch_proj(patch_i)
399	    //   + pos[1+i].  Build h0 into layer_in[0].
400	    // patch_proj -> rows 1..16 of layer_in[0] (write into a temporary region of
401	    // qkv, then add pos; but simplest: compute proj directly into layer_in[0]
402	    // rows 1.. via a linear over the 16 patch rows, with pos added after).
403	    // Step 1: cls row (position 0).
404	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x)
405	        sm->layer_in[0][0][j] = w.cls[j] + w.pos[j];   // pos[0] == w.pos + 0
406	    // Step 2: patch_proj over the 16 patch rows into ctx scratch [16,d].
407	    vit_linear(&sm->patch[0][0], vit::kPatch, w.patch_w, w.patch_b, vit::kD,
408	               &sm->ctx[0][0], vit::kNPatch);   // ctx[0..15] := proj
409	    // Step 3: add pos[1+i] -> layer_in[0] rows 1..16.
410	    for (int idx = threadIdx.x; idx < vit::kNPatch * vit::kD; idx += blockDim.x) {
411	        const int i = idx / vit::kD, j = idx % vit::kD;
412	        sm->layer_in[0][1 + i][j] = sm->ctx[i][j]
413	                                  + w.pos[(int64_t)(1 + i) * vit::kD + j];
414	    }
415	    __syncthreads();
416	
417	    for (int li = 0; li < vit::kLayers; ++li) {
418	        const VitWeights::Layer& L = w.layer[li];
419	        float* hin = &sm->layer_in[li][0][0];   // [kSeq, kD]
420	        // qkv = hin @ in_w^T + in_b -> [kSeq, 3d]
421	        vit_linear(hin, vit::kD, L.in_w, L.in_b, 3 * vit::kD, &sm->qkv[0][0],
422	                   vit::kSeq);
423	        // FULL attention -> sm->ctx, sm->attn.
424	        vit_attention(sm);
425	        // a = ctx @ out_w^T + out_b -> x1 (temporary 'a').
426	        vit_linear(&sm->ctx[0][0], vit::kD, L.out_w, L.out_b, vit::kD,
427	                   &sm->x1[0][0], vit::kSeq);   // x1 holds 'a' for now
428	        // r1 = hin + a -> ctx (reuse). n1(r1) -> x1.
429	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
430	            const int s = idx / vit::kD, j = idx % vit::kD;
431	            sm->ctx[s][j] = hin[s * vit::kD + j] + sm->x1[s][j];   // ctx := r1
432	        }
433	        __syncthreads();
434	        vit_layernorm_fwd(&sm->ctx[0][0], L.n1_w, L.n1_b, &sm->x1[0][0],
435	                          &sm->n1_xhat[0][0], &sm->n1_inv[0], sm->red);
436	        // FFN: ff0 = x1 @ ff0_w^T + ff0_b; g = gelu(ff0); ff2 = g @ ff2_w^T + b.
437	        vit_linear(&sm->x1[0][0], vit::kD, L.ff0_w, L.ff0_b, vit::kDff,
438	                   &sm->ff0[0][0], vit::kSeq);
439	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kDff; idx += blockDim.x)
440	            sm->gact[idx / vit::kDff][idx % vit::kDff] =
441	                vit_gelu(sm->ff0[idx / vit::kDff][idx % vit::kDff]);
442	        __syncthreads();
443	        // ff2 -> ctx scratch (reuse), then r2 = x1 + ff2, n2(r2) -> next layer_in.
444	        vit_linear(&sm->gact[0][0], vit::kDff, L.ff2_w, L.ff2_b, vit::kD,
445	                   &sm->ctx[0][0], vit::kSeq);   // ctx := ff2
446	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
447	            const int s = idx / vit::kD, j = idx % vit::kD;
448	            sm->ctx[s][j] = sm->x1[s][j] + sm->ctx[s][j];   // ctx := r2
449	        }
450	        __syncthreads();
451	        float* dst = (li + 1 < vit::kLayers) ? &sm->layer_in[li + 1][0][0]
452	                                             : &sm->final_in[0][0];
453	        vit_layernorm_fwd(&sm->ctx[0][0], L.n2_w, L.n2_b, dst,
454	                          &sm->n2_xhat[0][0], &sm->n2_inv[0], sm->red);
455	    }
456	
457	    // Final norm on the CLS position (0) only, then head → logits → NLL.
458	    const float* hcls = &sm->final_in[0][0];
459	    float sum = 0.0f;
460	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) sum += hcls[j];
461	    float mean = vit_block_sum(sum, sm->red) / (float)vit::kD;
462	    float vs = 0.0f;
463	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
464	        float c = hcls[j] - mean; vs += c * c;
465	    }
466	    float var = vit_block_sum(vs, sm->red) / (float)vit::kD;
467	    float inv = rsqrtf(var + vit::kLnEps);
468	    if (threadIdx.x == 0) sm->fn_inv[0] = inv;
469	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
470	        float xh = (hcls[j] - mean) * inv;
471	        sm->fn_xhat[0][j] = xh;                    // CLS xhat stored at row 0
472	        sm->x1[0][j] = xh * w.norm_w[j] + w.norm_b[j];   // x1[0] := hn
473	    }
474	    __syncthreads();
475	    // logits[o] = hn · out_w[o] + out_b[o]  (o over kVocab).
476	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
477	        const float* Wr = w.out_w + (int64_t)o * vit::kD;
478	        float acc = w.out_b[o];
479	        #pragma unroll 4
480	        for (int k = 0; k < vit::kD; ++k) acc += sm->x1[0][k] * Wr[k];
481	        sm->logits[o] = acc;
482	    }
483	    __syncthreads();
484	    // NLL (mean handled by /B in the loss reduce): logz - logits[target].
485	    float lmax = -CUDART_INF_F;
486	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x)
487	        lmax = fmaxf(lmax, sm->logits[o]);
488	    lmax = vit_block_max(lmax, sm->red);
489	    float es = 0.0f;
490	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x)
491	        es += __expf(sm->logits[o] - lmax);
492	    es = vit_block_sum(es, sm->red);
493	    float logz = lmax + __logf(es);
494	    return logz - sm->logits[target];   // sample NLL
495	}
496	
497	// ── Recompute one layer's forward intermediates into sm (qkv, x1, ff0, gact,
498	//    attn, and ctx := r2), reading from sm->layer_in[li]. Mirrors the fwd layer
499	//    body but leaves r2 in sm->ctx and x1 in sm->x1 for the backward chain. ─────
500	__device__ void vit_recompute_layer(const VitWeights& w, int li,
501	                                     VitSampleSmem* sm) {
502	    const VitWeights::Layer& L = w.layer[li];
503	    float* hin = &sm->layer_in[li][0][0];
504	    vit_linear(hin, vit::kD, L.in_w, L.in_b, 3 * vit::kD, &sm->qkv[0][0],
505	               vit::kSeq);
506	    vit_attention(sm);   // fills sm->attn + sm->ctx (== attention context)
507	    vit_linear(&sm->ctx[0][0], vit::kD, L.out_w, L.out_b, vit::kD, &sm->x1[0][0],
508	               vit::kSeq);   // x1 := a
509	    for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
510	        const int s = idx / vit::kD, j = idx % vit::kD;
511	        sm->ctx[s][j] = hin[s * vit::kD + j] + sm->x1[s][j];   // ctx := r1
512	    }
513	    __syncthreads();
514	    vit_layernorm_fwd(&sm->ctx[0][0], L.n1_w, L.n1_b, &sm->x1[0][0],
515	                      &sm->n1_xhat[0][0], &sm->n1_inv[0], sm->red);  // x1 := n1(r1)
516	    vit_linear(&sm->x1[0][0], vit::kD, L.ff0_w, L.ff0_b, vit::kDff, &sm->ff0[0][0],
517	               vit::kSeq);
518	    for (int idx = threadIdx.x; idx < vit::kSeq * vit::kDff; idx += blockDim.x) {
519	        const int s = idx / vit::kDff, j = idx % vit::kDff;
520	        sm->gact[s][j] = vit_gelu(sm->ff0[s][j]);
521	    }
522	    __syncthreads();
523	    // ff2 -> tmp (dh scratch, unused until bwd), r2 = x1 + ff2 -> ctx.
524	    vit_linear(&sm->gact[0][0], vit::kDff, L.ff2_w, L.ff2_b, vit::kD, &sm->dh[0][0],
525	               vit::kSeq);
526	    for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
527	        const int s = idx / vit::kD, j = idx % vit::kD;
528	        sm->ctx[s][j] = sm->x1[s][j] + sm->dh[s][j];   // ctx := r2
529	    }
530	    __syncthreads();
531	    // Fill n2 caches (we don't need n2's output for bwd, only xhat/inv).
532	    vit_layernorm_fwd(&sm->ctx[0][0], L.n2_w, L.n2_b, &sm->dh[0][0],
533	                      &sm->n2_xhat[0][0], &sm->n2_inv[0], sm->red);
534	    __syncthreads();
535	}
536	
537	// LayerNorm backward (same as decoder): given dy [kSeq,d] and cached (xhat,inv),
538	// returns dx [kSeq,d] into dx_out and ACCUMULATES dgamma/dbeta into gw/gb [d].
539	// Owner-thread rule for gw/gb: thread owns feature j (strided), sums over rows.
540	__device__ void vit_layernorm_bwd(
541	        const float* __restrict__ dy, const float* __restrict__ xhat,
542	        const float* __restrict__ inv, const float* __restrict__ gamma,
543	        float* __restrict__ dx_out, float* __restrict__ gw, float* __restrict__ gb,
544	        float* red, bool accum_affine) {
545	    if (accum_affine) {
546	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
547	            float dgw = 0.0f, dgb = 0.0f;
548	            #pragma unroll
549	            for (int s = 0; s < vit::kSeq; ++s) {
550	                float d = dy[s * vit::kD + j];
551	                dgb += d; dgw += d * xhat[s * vit::kD + j];
552	            }
553	            gw[j] += dgw; gb[j] += dgb;
554	        }
555	    }
556	    for (int s = 0; s < vit::kSeq; ++s) {
557	        const float* dyr = dy + s * vit::kD;
558	        const float* xhr = xhat + s * vit::kD;
559	        float sda = 0.0f, sdax = 0.0f;
560	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
561	            float dxhat = dyr[j] * gamma[j];
562	            sda += dxhat; sdax += dxhat * xhr[j];
563	        }
564	        sda = vit_block_sum(sda, red);
565	        sdax = vit_block_sum(sdax, red);
566	        float inv_s = inv[s];
567	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
568	            float dxhat = dyr[j] * gamma[j];
569	            dx_out[s * vit::kD + j] =
570	                inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)vit::kD);
571	        }
572	        __syncthreads();
573	    }
574	}
575	
576	// dW += dY^T @ X for a linear Y = X @ W^T + b. dY [kSeq,out], X [kSeq,in],
577	// dW [out,in]. db[o] += sum_s dY[s,o]. dX [kSeq,in] = dY @ W into dx_out
578	// (set or accumulate per set_dx).
579	//
580	// ldY/ldX/ldDX are the ROW STRIDES (leading dimensions) of dY/X/dx_out. They are
581	// EXPLICIT (no defaults) — IDENTICAL contract to the decoder's dec_linear_bwd.
582	// The smem scratch buffers this is called on are 2D arrays whose DECLARED width
583	// (kDff=512 for ff0/gact) DIFFERS from the logical row width passed as
584	// out_dim/in_dim (dctx=kD=128, dqkv=3*kD=384). The original packed-stride form
585	// (dY[s*out_dim+o], X[s*in_dim+i], dx_out[s*in_dim+i]) silently read/wrote the
586	// WRONG rows at both attention-seam call sites: only row 0 partially landed,
587	// rows 1.. hit stale recomputed values — forward stayed exact while every grad
588	// upstream of attention was garbage (params decayed to zero under weight decay;
589	// train acc pinned at 1/97). The CPU structural mirror (vit_kernel_mirror.py)
590	// does NOT catch it (it indexes buffers semantically, not by flat offset), so the
591	// stride is now part of the call contract. W/dW stay at in_dim — those are the
592	// genuinely-packed param/grad tensors, not smem scratch.
593	__device__ void vit_linear_bwd(
594	        const float* __restrict__ dY, const float* __restrict__ X,
595	        const float* __restrict__ W, int in_dim, int out_dim,
596	        float* __restrict__ dW, float* __restrict__ db,
597	        float* __restrict__ dx_out, bool set_dx,
598	        int ldY, int ldX, int ldDX) {
599	    const int wtot = out_dim * in_dim;
600	    for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
601	        const int o = idx / in_dim, i = idx % in_dim;
602	        float acc = 0.0f;
603	        #pragma unroll
604	        for (int s = 0; s < vit::kSeq; ++s)
605	            acc += dY[s * ldY + o] * X[s * ldX + i];
606	        dW[(int64_t)o * in_dim + i] += acc;
607	    }
608	    if (db != nullptr) {
609	        for (int o = threadIdx.x; o < out_dim; o += blockDim.x) {
610	            float acc = 0.0f;
611	            #pragma unroll
612	            for (int s = 0; s < vit::kSeq; ++s) acc += dY[s * ldY + o];
613	            db[o] += acc;
614	        }
615	    }
616	    const int xtot = vit::kSeq * in_dim;
617	    for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
618	        const int s = idx / in_dim, i = idx % in_dim;
619	        float acc = 0.0f;
620	        for (int o = 0; o < out_dim; ++o)
621	            acc += dY[s * ldY + o] * W[(int64_t)o * in_dim + i];
622	        if (set_dx) dx_out[s * ldDX + i] = acc;
623	        else dx_out[s * ldDX + i] += acc;
624	    }
625	    __syncthreads();
626	}
627	
628	// ────────────────────────────────────────────────────────────────────────────
629	//  BACKWARD for one sample (CTA-cooperative). Assumes vit_forward_sample has run
630	//  for THIS sample (so layer_in/final_in/fn caches/logits + sm->patch are live).
631	//  Accumulates every weight grad into the CTA's partial buffer `g`.
632	//
633	//  Transcribed from tests/hw/vit_oracle.py::vit_backward (structurally mirrored
634	//  in tests/hw/vit_kernel_mirror.py).
635	// ────────────────────────────────────────────────────────────────────────────
636	__device__ void vit_backward_sample(const VitWeights& w, const VitGrad& g,
637	                                     int target, int B, VitSampleSmem* sm) {
638	    // ── CE backward: dlogits = (softmax - onehot)/B. ──
639	    float lmax = -CUDART_INF_F;
640	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x)
641	        lmax = fmaxf(lmax, sm->logits[o]);
642	    lmax = vit_block_max(lmax, sm->red);
643	    float es = 0.0f;
644	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x)
645	        es += __expf(sm->logits[o] - lmax);
646	    es = vit_block_sum(es, sm->red);
647	    float inv_es = 1.0f / es;
648	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
649	        float sm_o = __expf(sm->logits[o] - lmax) * inv_es;
650	        float dl = (sm_o - ((o == target) ? 1.0f : 0.0f)) / (float)B;
651	        sm->logits[o] = dl;   // overwrite logits[] with dlogits in place
652	    }
653	    __syncthreads();
654	    // ── head (out): logits = hn @ out_w^T + out_b. hn recomputed from the cached
655	    //    final-norm: hn[j] = fn_xhat[0][j]*norm_w[j] + norm_b[j]. ──
656	    for (int o = threadIdx.x; o < vit::kVocab; o += blockDim.x) {
657	        float dl = sm->logits[o];
658	        g.out_b[o] += dl;
659	        float* gwrow = g.out_w + (int64_t)o * vit::kD;
660	        const float* xh = &sm->fn_xhat[0][0];
661	        #pragma unroll 4
662	        for (int j = 0; j < vit::kD; ++j) {
663	            float hn_j = xh[j] * w.norm_w[j] + w.norm_b[j];
664	            gwrow[j] += dl * hn_j;
665	        }
666	    }
667	    __syncthreads();
668	    // dhn[j] (feature-parallel) into dh row 0 scratch.
669	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
670	        float acc = 0.0f;
671	        for (int o = 0; o < vit::kVocab; ++o)
672	            acc += sm->logits[o] * w.out_w[(int64_t)o * vit::kD + j];
673	        sm->dh[0][j] = acc;   // dhn
674	    }
675	    __syncthreads();
676	    // ── final norm backward (single CLS row 0): dy=dhn, xhat=fn_xhat[0],
677	    //    inv=fn_inv[0]. Produces dh into dh[0]; zeros all other rows; accumulate
678	    //    dnorm_w/dnorm_b. Stage dy into ctx row 0. ──
679	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x)
680	        sm->ctx[0][j] = sm->dh[0][j];   // dy at CLS position
681	    __syncthreads();
682	    for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
683	        float d = sm->ctx[0][j];
684	        float xh = sm->fn_xhat[0][j];
685	        g.norm_b[j] += d; g.norm_w[j] += d * xh;
686	    }
687	    __syncthreads();
688	    {
689	        const float* dyr = &sm->ctx[0][0];
690	        const float* xhr = &sm->fn_xhat[0][0];
691	        float sda = 0.0f, sdax = 0.0f;
692	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
693	            float dxhat = dyr[j] * w.norm_w[j];
694	            sda += dxhat; sdax += dxhat * xhr[j];
695	        }
696	        sda = vit_block_sum(sda, sm->red);
697	        sdax = vit_block_sum(sdax, sm->red);
698	        float inv_s = sm->fn_inv[0];
699	        for (int j = threadIdx.x; j < vit::kD; j += blockDim.x) {
700	            float dxhat = dyr[j] * w.norm_w[j];
701	            for (int s = 0; s < vit::kSeq; ++s) sm->dh[s][j] = 0.0f;
702	            sm->dh[0][j] = inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)vit::kD);
703	        }
704	        __syncthreads();
705	    }
706	    // dh now = grad wrt the last layer's OUTPUT [kSeq,d] (only CLS pos 0 nonzero).
707	
708	    // ── per-layer backward (reverse). Each layer: recompute fwd intermediates,
709	    //    then apply the chain. The running adjoint `dh` is preserved across the
710	    //    recompute by SAVING it into final_in (free after fwd) around the
711	    //    recompute (which temporarily uses sm->dh as ff2 scratch). ─────────────
712	    for (int li = vit::kLayers - 1; li >= 0; --li) {
713	        const VitWeights::Layer& L = w.layer[li];
714	        const VitGrad::Layer& G = g.layer[li];
715	        // Save incoming adjoint dh into final_in — recompute clobbers sm->dh.
716	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
717	            const int s = idx / vit::kD, j = idx % vit::kD;
718	            sm->final_in[s][j] = sm->dh[s][j];
719	        }
720	        __syncthreads();
721	        vit_recompute_layer(w, li, sm);   // fills qkv,x1,ff0,gact,attn,ctx(=r2),caches
722	        // Restore dh (grad wrt h2 = n2 output).
723	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
724	            const int s = idx / vit::kD, j = idx % vit::kD;
725	            sm->dh[s][j] = sm->final_in[s][j];
726	        }
727	        __syncthreads();
728	        // n2 backward: dh -> dr2 (into ctx), accumulate n2 gamma/beta.
729	        vit_layernorm_bwd(&sm->dh[0][0], &sm->n2_xhat[0][0], &sm->n2_inv[0],
730	                          L.n2_w, &sm->ctx[0][0], G.n2_w, G.n2_b, sm->red, true);
731	        // r2 = x1 + ff2 -> dx1 (residual) := dr2 into fn_xhat; dr2 stays in ctx.
732	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
733	            const int s = idx / vit::kD, j = idx % vit::kD;
734	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx1 := dr2 (residual part)
735	        }
736	        __syncthreads();
737	        // ff.2 backward. dW_ff2 += dr2^T @ g; db_ff2 += Σ dr2; then dff0 written
738	        // OVER gact (its forward value consumed by the dW GEMM first).
739	        {
740	            const float* dY = &sm->ctx[0][0];   // dr2 [kSeq,d]
741	            const float* X = &sm->gact[0][0];   // g [kSeq,4d]
742	            const int wtot = vit::kD * vit::kDff;
743	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
744	                const int o = idx / vit::kDff, i = idx % vit::kDff;
745	                float acc = 0.0f;
746	                #pragma unroll
747	                for (int s = 0; s < vit::kSeq; ++s)
748	                    acc += dY[s * vit::kD + o] * X[s * vit::kDff + i];
749	                G.ff2_w[(int64_t)o * vit::kDff + i] += acc;
750	            }
751	            for (int o = threadIdx.x; o < vit::kD; o += blockDim.x) {
752	                float acc = 0.0f;
753	                #pragma unroll
754	                for (int s = 0; s < vit::kSeq; ++s) acc += dY[s * vit::kD + o];
755	                G.ff2_b[o] += acc;
756	            }
757	            __syncthreads();
758	            const int xtot = vit::kSeq * vit::kDff;
759	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
760	                const int s = idx / vit::kDff, i = idx % vit::kDff;
761	                float dg = 0.0f;
762	                for (int o = 0; o < vit::kD; ++o)
763	                    dg += dY[s * vit::kD + o] * L.ff2_w[(int64_t)o * vit::kDff + i];
764	                sm->gact[s][i] = dg * vit_gelu_grad(sm->ff0[s][i]);  // gact := dff0
765	            }
766	            __syncthreads();
767	        }
768	        // ff.0 backward: dY=dff0(=gact), X=x1 -> dW ff0, db ff0, dx1 += dff0 @ ff0_w.
769	        {
770	            const float* dY = &sm->gact[0][0];   // dff0 [kSeq,4d]
771	            const float* X = &sm->x1[0][0];      // x1 [kSeq,d]
772	            const int wtot = vit::kDff * vit::kD;
773	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
774	                const int o = idx / vit::kD, i = idx % vit::kD;
775	                float acc = 0.0f;
776	                #pragma unroll
777	                for (int s = 0; s < vit::kSeq; ++s)
778	                    acc += dY[s * vit::kDff + o] * X[s * vit::kD + i];
779	                G.ff0_w[(int64_t)o * vit::kD + i] += acc;
780	            }
781	            for (int o = threadIdx.x; o < vit::kDff; o += blockDim.x) {
782	                float acc = 0.0f;
783	                #pragma unroll
784	                for (int s = 0; s < vit::kSeq; ++s) acc += dY[s * vit::kDff + o];
785	                G.ff0_b[o] += acc;
786	            }
787	            __syncthreads();
788	            const int xtot = vit::kSeq * vit::kD;
789	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
790	                const int s = idx / vit::kD, i = idx % vit::kD;
791	                float acc = 0.0f;
792	                for (int o = 0; o < vit::kDff; ++o)
793	                    acc += dY[s * vit::kDff + o] * L.ff0_w[(int64_t)o * vit::kD + i];
794	                sm->fn_xhat[s][i] += acc;   // dx1 += FFN path
795	            }
796	            __syncthreads();
797	        }
798	        // dx1 (in fn_xhat) -> n1 backward -> dr1 (into ctx). accumulate n1 g/b.
799	        vit_layernorm_bwd(&sm->fn_xhat[0][0], &sm->n1_xhat[0][0], &sm->n1_inv[0],
800	                          L.n1_w, &sm->ctx[0][0], G.n1_w, G.n1_b, sm->red, true);
801	        // r1 = x_in + a -> da = dr1; dx_in := dr1 (residual) into fn_xhat. da in ctx.
802	        for (int idx = threadIdx.x; idx < vit::kSeq * vit::kD; idx += blockDim.x) {
803	            const int s = idx / vit::kD, j = idx % vit::kD;
804	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx_in := dr1 (residual)
805	        }
806	        __syncthreads();
