838	            const int rem = r % (vit::kHeads * vit::kDhead);
839	            const int hh = rem / vit::kDhead, t = rem % vit::kDhead;
840	            const int qoff = hh * vit::kDhead;
841	            float acc = 0.0f;
842	            #pragma unroll
843	            for (int qi = 0; qi < vit::kSeq; ++qi)   // FULL (no causal qi>=kj)
