71	// (dX) dX[m,kin] = Σ_out dY[m,out]·W[out,kin]. GEMM: A=dY (m, out=K), B=W staged
72	// so n=kin, k=out → srcB(n=kin, k=out) reads W[out, kin] (PHYSICAL TRANSPOSE).
73	// Here N (the wgmma N) = Kin (the in_dim), and the contraction K = Nout.
74	template <int N>
75	__global__ void __launch_bounds__(256)
76	gemm_dx_kernel(const __nv_bfloat16* __restrict__ dY,   // [M, Nout] row-major
77	               const __nv_bfloat16* __restrict__ W,    // [Nout, N] row-major (in_dim=N)
78	               float* __restrict__ dX,                 // [M, N] row-major out
79	               int Nout) {
80	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
81	    extern __shared__ __nv_bfloat16 smem[];
82	    __nv_bfloat16* sA = smem;
83	    __nv_bfloat16* sB = sA + 64 * 16;
84	    const int M = dectc::kTileM;
85	    const int m_atoms = M / 64;
86	    const int k_steps = Nout / 16;
87	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return dY[(int64_t)m * Nout + k]; };
88	    // B[n=kin, k=out] = W[out, kin]  → transposed read.
89	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 { return W[(int64_t)k * N + n]; };
90	    auto out  = [&] (int m, int n, float v) { if (m < M) dX[(int64_t)m * N + n] = v; };
91	    dectc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/2>(
92	        0, m_atoms, /*n_real=*/N, k_steps, srcA, srcB, out, sA, sB);
93	#else
94	    (void)dY; (void)W; (void)dX; (void)Nout;
95	#endif
96	}
