98	// (dW) dW[out,in] = Σ_t dY[t,out]·X[t,in]. GEMM: A=dY staged so m=out, k=t
99	// (dY is [t,out] → srcA(m=out,k=t)=dY[t,out], TRANSPOSE); B=X staged so n=in,
100	// k=t (X is [t,in] → srcB(n=in,k=t)=X[t,in], TRANSPOSE). K = T (the full token
101	// dim → MULTI-k-step, the stride-bug gate). M here is Nout (rows of dW), tiled
102	// as kAtomsM stacked m64 atoms; N is the wgmma N = in_dim.
103	// dW: M = Nout (rows of dW, up to 512 = 8 atoms), N = in_dim (<=128), K = T.
104	template <int N>
105	__global__ void __launch_bounds__(256)
106	gemm_dw_kernel(const __nv_bfloat16* __restrict__ dY,   // [T, Nout] row-major
107	               const __nv_bfloat16* __restrict__ X,    // [T, N] row-major (in_dim=N)
108	               float* __restrict__ dW,                 // [Nout, N] row-major out
109	               int Nout, int T) {
110	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
111	    extern __shared__ __nv_bfloat16 smem[];
112	    __nv_bfloat16* sA = smem;
113	    __nv_bfloat16* sB = sA + 64 * 16;
114	    const int k_steps = T / 16;
115	    const int m_atoms = (Nout + 63) / 64;        // up to 8 for Nout=512
116	    // A[m=out, k=t] = dY[t, out]  → transposed read.
117	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
118	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
119	    // B[n=in, k=t] = X[t, in]     → transposed read.
120	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 { return X[(int64_t)k * N + n]; };
121	    auto out  = [&] (int m, int n, float v) { if (m < Nout) dW[(int64_t)m * N + n] = v; };
122	    dectc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/8>(
123	        0, m_atoms, /*n_real=*/N, k_steps, srcA, srcB, out, sA, sB);
124	#else
125	    (void)dY; (void)X; (void)dW; (void)Nout; (void)T;
126	#endif
127	}
128	
129	static size_t arena_bytes() { return (size_t)(64 * 16 + 128 * 16) * sizeof(__nv_bfloat16) + 256; }
130	
131	template <int N>
132	static torch::Tensor run_fwd(torch::Tensor X, torch::Tensor W, int Kin, int Nout) {
133	    TORCH_CHECK(X.scalar_type() == torch::kBFloat16 && W.scalar_type() == torch::kBFloat16);
134	    TORCH_CHECK(X.is_cuda() && W.is_cuda() && X.is_contiguous() && W.is_contiguous());
135	    auto D = torch::zeros({dectc::kTileM, Nout}, torch::dtype(torch::kFloat32).device(X.device()));
136	    size_t smem = arena_bytes();
137	    auto stream = at::cuda::getCurrentCUDAStream();
138	    cudaFuncSetAttribute(gemm_fwd_kernel<N>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
139	    gemm_fwd_kernel<N><<<1, 256, smem, stream>>>(
140	        reinterpret_cast<const __nv_bfloat16*>(X.data_ptr()),
141	        reinterpret_cast<const __nv_bfloat16*>(W.data_ptr()), D.data_ptr<float>(), Kin, Nout);
142	    C10_CUDA_CHECK(cudaGetLastError());
143	    return D;
144	}
145	template <int N>
146	static torch::Tensor run_dx(torch::Tensor dY, torch::Tensor W, int Nout) {
147	    auto dX = torch::zeros({dectc::kTileM, N}, torch::dtype(torch::kFloat32).device(dY.device()));
148	    size_t smem = arena_bytes();
149	    auto stream = at::cuda::getCurrentCUDAStream();
150	    cudaFuncSetAttribute(gemm_dx_kernel<N>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
151	    gemm_dx_kernel<N><<<1, 256, smem, stream>>>(
152	        reinterpret_cast<const __nv_bfloat16*>(dY.data_ptr()),
153	        reinterpret_cast<const __nv_bfloat16*>(W.data_ptr()), dX.data_ptr<float>(), Nout);
154	    C10_CUDA_CHECK(cudaGetLastError());
155	    return dX;
156	}
157	template <int N>
158	static torch::Tensor run_dw(torch::Tensor dY, torch::Tensor X, int Nout, int T) {
159	    auto dW = torch::zeros({Nout, N}, torch::dtype(torch::kFloat32).device(dY.device()));
160	    size_t smem = arena_bytes();
161	    auto stream = at::cuda::getCurrentCUDAStream();
162	    cudaFuncSetAttribute(gemm_dw_kernel<N>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
163	    gemm_dw_kernel<N><<<1, 256, smem, stream>>>(
164	        reinterpret_cast<const __nv_bfloat16*>(dY.data_ptr()),
165	        reinterpret_cast<const __nv_bfloat16*>(X.data_ptr()), dW.data_ptr<float>(), Nout, T);
166	    C10_CUDA_CHECK(cudaGetLastError());
167	    return dW;
168	}
169	
170	// Runtime-N dispatch to the compile-time template (decoder's N set: 128 in/out/
171	// ff0(dX)/ff2(dX); ff0 fwd N=dff=512 tiled as 4x128 by the real header, but the
172	// micro-gate exercises the atom widths the engine issues: 128 (and 96 for head)).
173	static torch::Tensor gemm_fwd(torch::Tensor X, torch::Tensor W, int N, int Kin, int Nout) {
174	    switch (N) { case 96: return run_fwd<96>(X, W, Kin, Nout); case 128: return run_fwd<128>(X, W, Kin, Nout);
175	                 default: TORCH_CHECK(false, "fwd N ", N); }
176	}
177	static torch::Tensor gemm_dx(torch::Tensor dY, torch::Tensor W, int N, int Nout) {
178	    switch (N) { case 96: return run_dx<96>(dY, W, Nout); case 128: return run_dx<128>(dY, W, Nout);
179	                 default: TORCH_CHECK(false, "dx N ", N); }
180	}
181	static torch::Tensor gemm_dw(torch::Tensor dY, torch::Tensor X, int N, int Nout, int T) {
182	    switch (N) { case 96: return run_dw<96>(dY, X, Nout, T); case 128: return run_dw<128>(dY, X, Nout, T);
183	                 default: TORCH_CHECK(false, "dw N ", N); }
184	}
185	
186	PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
187	    m.def("gemm_fwd", &gemm_fwd, "TC fwd Y=X@W^T (TILE_M x N), bf16/fp32acc");
188	    m.def("gemm_dx",  &gemm_dx,  "TC dX=dY@W (W transposed-staged), bf16/fp32acc");
189	    m.def("gemm_dw",  &gemm_dw,  "TC dW=dY^T@X (both transposed-staged, K=T), bf16/fp32acc");
